SELECT ?dept_name (SUM(?studentFlag) AS ?students) (SUM(?instructorFlag) AS ?instructors)
WHERE {
  # -------------------------------------------------
  # Students from college 1 (need to resolve dept_code -> dept_name)
  # -------------------------------------------------
  {
    SERVICE <http://host.docker.internal:3030/college_1__student/sparql> {
      ?s a <http://valuenet/ontop/student> ;
         student:dept_code ?dept_code .
