    SERVICE <http://host.docker.internal:3030/college_1__department/sparql> {
      ?d a <http://valuenet/ontop/department> ;
         department:dept_code ?dept_code ;
         department:dept_name ?dept_name .
    }
    BIND (1 AS ?studentFlag)
    BIND (0 AS ?instructorFlag)
  }
  UNION
  # -------------------------------------------------
  # Students from college 2 (dept_name already present)
  # -------------------------------------------------
  {
    SERVICE <http://host.docker.internal:3030/college_2__student/sparql> {
      ?s a <http://valuenet/ontop/student> ;
         student:dept_name ?dept_name .
    }
    BIND (1 AS ?studentFlag)
    BIND (0 AS ?instructorFlag)
  }
  UNION
  # -------------------------------------------------
  # Instructors from college 2
  # -------------------------------------------------
  {
    SERVICE <http://host.docker.internal:3030/college_2__instructor/sparql> {
      ?i a <http://valuenet/ontop/instructor> ;
         instructor:dept_name ?dept_name .
    }
    BIND (0 AS ?studentFlag)
    BIND (1 AS ?instructorFlag)
  }
}
GROUP BY ?dept_name
ORDER BY ?dept_name

