SELECT ?staff_id ?fullName ?minDur WHERE {

  # ---- sub‑query: compute the shortest assignment per staff ----
  {
    SELECT ?staff_id (MIN(?duration) AS ?minDur) WHERE {

      # Department store assignments
      {
        SERVICE <http://host.docker.internal:3030/department_store__staff_department_assignments/sparql> {
          ?assign a <http://valuenet/ontop/staff_department_assignments> ;
                  <http://valuenet/ontop/staff_department_assignments#staff_id> ?staff_id ;
                  <http://valuenet/ontop/staff_department_assignments#date_assigned_from> ?from ;
                  <http://valuenet/ontop/staff_department_assignments#date_assigned_to>   ?to .
          BIND( xsd:dateTime(?to) - xsd:dateTime(?from) AS ?duration )
        }
      }

      UNION

      # Project staff assignments
      {
        SERVICE <http://host.docker.internal:3030/tracking_grants_for_research__project_staff/sparql> {
          ?proj a <http://valuenet/ontop/project_staff> ;
                <http://valuenet/ontop/project_staff#staff_id> ?staff_id ;
                <http://valuenet/ontop/project_staff#date_from>   ?from ;
                <http://valuenet/ontop/project_staff#date_to>     ?to .
          BIND( xsd:dateTime(?to) - xsd:dateTime(?from) AS ?duration )
        }
      }

    } GROUP BY ?staff_id
    ORDER BY ASC(?minDur)
    LIMIT 1               # keep only the staff with the overall shortest assignment
  }

  # ---- fetch the staff's name from the staff endpoint ----
  SERVICE <http://host.docker.internal:3030/driving_school__staff/sparql> {
    ?staff a <http://valuenet/ontop/staff> ;
           <http://valuenet/ontop/staff#staff_id>      ?staff_id ;
           <http://valuenet/ontop/staff#first_name>    ?firstName .
    OPTIONAL { ?staff <http://valuenet/ontop/staff#middle_name> ?middleName . }
    OPTIONAL { ?staff <http://valuenet/ontop/staff#last_name>   ?lastName . }

    BIND( STR(?firstName) AS ?fn )
    BIND( COALESCE( STR(?middleName), "" ) AS ?mn )
    BIND( COALESCE( STR(?lastName), "" )   AS ?ln )

    BIND( CONCAT(
            ?fn,
            IF( ?mn != "", CONCAT(" ", ?mn), "" ),
            IF( ?ln != "", CONCAT(" ", ?ln), "" )
          ) AS ?fullName )
  }
}
