            <http://valuenet/ontop/addresses#address_id>               ?addrId ;
            <http://valuenet/ontop/addresses#line_1_number_building>  ?street .
      OPTIONAL { ?addr <http://valuenet/ontop/addresses#city>               ?city . }
      OPTIONAL { ?addr <http://valuenet/ontop/addresses#state_province_county> ?state . }
      OPTIONAL { ?addr <http://valuenet/ontop/addresses#zip_postcode>       ?zip . }

      BIND ( CONCAT(
                ?street,
                IF(BOUND(?city),  CONCAT(", ", ?city),  ""),
                IF(BOUND(?state), CONCAT(", ", ?state), ""),
                IF(BOUND(?zip),   CONCAT(" ", ?zip),   "")
             ) AS ?location )
    }
  }
