            <http://valuenet/ontop/customers#customer_address> ?address .
      FILTER ( CONTAINS( LCASE(?fullName), "linda" ) )
      BIND ( ?address AS ?location )
    }
  }
  UNION
  # -------------------------------------------------
  # 5. cre_drama_workshop_groups__customers + (addresses endpoint not provided, 
  #    but we use the same dataset for address if needed – here we only have address_id,
  #    so we attempt to get the address string if an address endpoint existed)
  # -------------------------------------------------
